#include<iostream>
#include<cmath>
using namespace std;

class Diem{
	private:
		float hoanhdo;
		float tungdo;
	public:
		Diem(){
			hoanhdo=0;
			tungdo=0;
		}
		friend istream& operator>>(istream &is, Diem &d){
			cout<<"Nhap hoanh do va tung do:"<<endl;
			is>>d.hoanhdo>>d.tungdo;
			return is;
		}
		friend ostream& operator<<(ostream &os, Diem &d){
			os<<"("<<d.hoanhdo<<","<<d.tungdo<<")";
		}
		float KhoangCach(){
			return sqrt(hoanhdo*hoanhdo+tungdo*tungdo);
		}
};
int main(){
	int n;
	cout<<"Nhap n:";
	cin>>n;
	Diem a[100];
	for(int i=0;i<n;i++){
		cin>>a[i];
	}
	int tong=0;
	for(int i=0;i<n;i++){
		tong+=a[i].KhoangCach();
	}
	cout<<"\nTong:"<<tong;
	int t=0;
	for(int i=12;i<n;i++){
		if(a[i].KhoangCach()<a[t].KhoangCach()){
			t=i;
		}
	}
	cout<<"\nDiem gan goc toa do nhat:"<<a[t];
	return 0;
}

